convergences=[
 dict(date="1820-06-06",label="The Queen enters London; the King's green bags reach Parliament",eyes=["george4","greville"],note="On the same day the King's formal message asked the Lords to judge his wife, Greville was riding out to watch the crowds cheer her in. The legal case and the street case began together."),
 dict(date="1820-08-07",label="The Queen's open letter to the King",eyes=["caroline","creevey","cobbett"],note="Caroline's letter, probably in Cobbett's words, cast her as a wronged wife denied a fair court; that same day Creevey, at Knowsley, thought neither spouse deserved sympathy. Radical pen, royal signature and Whig shrug in one day."),
 dict(date="1820-08-17",label="The hearing opens in the Lords",eyes=["lords-record","creevey"],note="The record gives the division of 206 to 41 against dropping the bill; Creevey, writing in the House, gives the Queen's veil, her curtsies and the peers' mood, which the record leaves out."),
 dict(date="1820-08-22",label="Majocchi under cross-examination",eyes=["majocchi","brougham","hone"],note="The record preserves the witness's 'I do not remember' and the interpreters' argument over its meaning; Brougham built his defence on it; within weeks Hone had made it the catchphrase of the season."),
 dict(date="1820-10-03",label="Brougham's defence speech (3–4 October)",eyes=["brougham","creevey","greville"],note="The Hansard text gives the argument; Creevey, sceptical of Brougham, grants it was as good as expected; Greville, no Whig, calls it the finest oratory in years and expects the bill to fall."),
 dict(date="1820-10-24",label="Denman sums up for the Queen",eyes=["denman","lieven","george4"],note="In the Lords Denman called the Queen the victim of perjury and likened the King to Nero, a passage Creevey singled out for praise; that week Lieven was writing about the King's chandeliers at Brighton, and the King was writing of the defence's lies."),
 dict(date="1820-11-10",label="The bill is abandoned",eyes=["lords-record","plumer-ward","creevey"],note="The record gives 108 to 99 and Liverpool's motion; the government man records it flatly; the Whig records Eldon's lone 'Not content' and a House undoing itself."),
 dict(date="1821-08-08",label="The Queen's death (7 August 1821) and its news",eyes=["creevey","brougham"],note="Brougham, at Brandenburgh House, carried her last words; Creevey passed them on and within days was doubting whether Brougham had served her well."),
]

